INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "韩建使张行思告八王谋杀劫驾。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：韩建奏：“防城将张行思等告睦、济、韶、通、彭、韩、仪、陈八王谋杀臣，劫车驾幸河中。”建恶诸王典兵，故使行思等告之。；核对说明：告变由韩建指使，谋杀劫驾为指控，不建八王确实谋反或已迁河中事件。八王原名未载，不按封号猜实名。", "status": "draft", "id": "7944ceee-3206-5371-8195-09be18f82af0", "subject_id": "2ea00e19-6ad9-513a-a4ea-2d307ced20b5", "source_id": "6c9670cd-311b-50e5-8a4e-07871c7458a4"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "897年正月甲申", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：韩建奏：“防城将张行思等告睦、济、韶、通、彭、韩、仪、陈八王谋杀臣，劫车驾幸河中。”建恶诸王典兵，故使行思等告之。；核对说明：告变由韩建指使，谋杀劫驾为指控，不建八王确实谋反或已迁河中事件。八王原名未载，不按封号猜实名。", "status": "draft", "id": "83c904e0-4604-53c9-9fbb-a64f75c488a8", "subject_id": "2ea00e19-6ad9-513a-a4ea-2d307ced20b5", "source_id": "6c9670cd-311b-50e5-8a4e-07871c7458a4"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记韩建：指使奏告者。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：春，正月，甲申，韩建奏：“防城将张行思等告睦、济、韶、通、彭、韩、仪、陈八王谋杀臣，劫车驾幸河中。”建恶诸王典兵，故使行思等告之。上大惊，召建谕之，建称疾不入。令诸王诣建自陈，建表称：“诸王忽诣臣理所，不测事端。臣详酌事体，不应与诸王相见。”又称：“诸王当自避嫌疑，不可轻为举措。陛下若以友爱含容，请依旧制，令归十六宅，妙选师傅，教以诗书，不令典兵预政。”且曰：“乞散彼乌合之兵，用光麟趾之化。”建虑上不从，仍引麾下精兵围行宫，表疏连上。上不得已，是夕，诏诸王所领军士并纵归田里，诸王勒归十六宅，其甲兵并委韩建收掌。建又奏：“陛下选贤任能，足清祸乱，何必别置殿后四军。纵有厚薄之恩，乖无偏无党之道。且所聚皆坊市无赖奸猾之徒，平居犹思祸变，临难必不为用，而使之张弓挟刃，密迩皇舆，臣窃寒心，乞皆罢。”遣诏亦从之。于是殿后四军二万馀人悉散，天子之亲军尽矣。捧日都头李筠，石门扈从功第一，建复奏斩于大云桥。建又奏：“玄宗之末，永王璘暂出江南，遽谋不轨。代宗时吐蕃入寇，光启中硃玫乱常，皆援立宗支以系人望。今诸王衔命四方者，乞皆召还。”又奏：“诸方士出入禁庭，眩惑圣听，宜皆禁止，无得入宫。”诏悉从之。建既幽诸王于别第，知上意不悦，乃奏请立德王为太子，欲以解之。丁亥，诏立德王祐为皇太子，仍更名裕。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "821775b7-9d79-59b1-8d68-7bba5d29e179", "subject_id": "0a022fc7-47b3-5530-98ad-3625fceab9a5", "source_id": "6c9670cd-311b-50e5-8a4e-07871c7458a4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "韩建：指使奏告者。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：韩建奏：“防城将张行思等告睦、济、韶、通、彭、韩、仪、陈八王谋杀臣，劫车驾幸河中。”建恶诸王典兵，故使行思等告之。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "3479abcd-2839-5867-86cc-a765cbf036fc", "subject_id": "3d491526-a6ea-501d-852d-0d3a2facc7f7", "source_id": "6c9670cd-311b-50e5-8a4e-07871c7458a4"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记张行思：被使告变者。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：春，正月，甲申，韩建奏：“防城将张行思等告睦、济、韶、通、彭、韩、仪、陈八王谋杀臣，劫车驾幸河中。”建恶诸王典兵，故使行思等告之。上大惊，召建谕之，建称疾不入。令诸王诣建自陈，建表称：“诸王忽诣臣理所，不测事端。臣详酌事体，不应与诸王相见。”又称：“诸王当自避嫌疑，不可轻为举措。陛下若以友爱含容，请依旧制，令归十六宅，妙选师傅，教以诗书，不令典兵预政。”且曰：“乞散彼乌合之兵，用光麟趾之化。”建虑上不从，仍引麾下精兵围行宫，表疏连上。上不得已，是夕，诏诸王所领军士并纵归田里，诸王勒归十六宅，其甲兵并委韩建收掌。建又奏：“陛下选贤任能，足清祸乱，何必别置殿后四军。纵有厚薄之恩，乖无偏无党之道。且所聚皆坊市无赖奸猾之徒，平居犹思祸变，临难必不为用，而使之张弓挟刃，密迩皇舆，臣窃寒心，乞皆罢。”遣诏亦从之。于是殿后四军二万馀人悉散，天子之亲军尽矣。捧日都头李筠，石门扈从功第一，建复奏斩于大云桥。建又奏：“玄宗之末，永王璘暂出江南，遽谋不轨。代宗时吐蕃入寇，光启中硃玫乱常，皆援立宗支以系人望。今诸王衔命四方者，乞皆召还。”又奏：“诸方士出入禁庭，眩惑圣听，宜皆禁止，无得入宫。”诏悉从之。建既幽诸王于别第，知上意不悦，乃奏请立德王为太子，欲以解之。丁亥，诏立德王祐为皇太子，仍更名裕。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "d383cf2e-9965-5d65-a963-fef8cff372b9", "subject_id": "5009ea10-a762-5360-8cd5-e1f8aae9bd43", "source_id": "6c9670cd-311b-50e5-8a4e-07871c7458a4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张行思：被使告变者。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：韩建奏：“防城将张行思等告睦、济、韶、通、彭、韩、仪、陈八王谋杀臣，劫车驾幸河中。”建恶诸王典兵，故使行思等告之。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "cc0fd7c2-d0dc-51ea-b5ef-6762d26931ed", "subject_id": "f0429188-9b00-59d0-8f8e-52a656893d9e", "source_id": "6c9670cd-311b-50e5-8a4e-07871c7458a4"}, {"subject_table": "event", "field_path": "description", "claim_text": "昭宗召韩建谕之，韩建称疾不入。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：上大惊，召建谕之，建称疾不入。；核对说明：称疾是借口式原记，不补真实疾病诊断。", "status": "draft", "id": "3798b59b-5c24-585f-a458-04d90a762ff6", "subject_id": "d43202aa-f65f-57f9-93e6-1b3339d83739", "source_id": "6c9670cd-311b-50e5-8a4e-07871c7458a4"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "897年正月甲申告变后", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：上大惊，召建谕之，建称疾不入。；核对说明：称疾是借口式原记，不补真实疾病诊断。", "status": "draft", "id": "ea190347-183a-539f-82cc-1bd66512bef3", "subject_id": "d43202aa-f65f-57f9-93e6-1b3339d83739", "source_id": "6c9670cd-311b-50e5-8a4e-07871c7458a4"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李杰：召谕者。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：春，正月，甲申，韩建奏：“防城将张行思等告睦、济、韶、通、彭、韩、仪、陈八王谋杀臣，劫车驾幸河中。”建恶诸王典兵，故使行思等告之。上大惊，召建谕之，建称疾不入。令诸王诣建自陈，建表称：“诸王忽诣臣理所，不测事端。臣详酌事体，不应与诸王相见。”又称：“诸王当自避嫌疑，不可轻为举措。陛下若以友爱含容，请依旧制，令归十六宅，妙选师傅，教以诗书，不令典兵预政。”且曰：“乞散彼乌合之兵，用光麟趾之化。”建虑上不从，仍引麾下精兵围行宫，表疏连上。上不得已，是夕，诏诸王所领军士并纵归田里，诸王勒归十六宅，其甲兵并委韩建收掌。建又奏：“陛下选贤任能，足清祸乱，何必别置殿后四军。纵有厚薄之恩，乖无偏无党之道。且所聚皆坊市无赖奸猾之徒，平居犹思祸变，临难必不为用，而使之张弓挟刃，密迩皇舆，臣窃寒心，乞皆罢。”遣诏亦从之。于是殿后四军二万馀人悉散，天子之亲军尽矣。捧日都头李筠，石门扈从功第一，建复奏斩于大云桥。建又奏：“玄宗之末，永王璘暂出江南，遽谋不轨。代宗时吐蕃入寇，光启中硃玫乱常，皆援立宗支以系人望。今诸王衔命四方者，乞皆召还。”又奏：“诸方士出入禁庭，眩惑圣听，宜皆禁止，无得入宫。”诏悉从之。建既幽诸王于别第，知上意不悦，乃奏请立德王为太子，欲以解之。丁亥，诏立德王祐为皇太子，仍更名裕。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "348daf04-e62a-52c1-b10a-a12bfc7df71b", "subject_id": "48935190-c754-5bda-bdcd-382c77cb2de0", "source_id": "6c9670cd-311b-50e5-8a4e-07871c7458a4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "唐昭宗：召谕者。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：上大惊，召建谕之，建称疾不入。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "b42446f1-6386-597a-b9c6-ca792b071d9d", "subject_id": "f5866c6e-eff0-523e-8417-f192194b1b48", "source_id": "6c9670cd-311b-50e5-8a4e-07871c7458a4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "韩建：称疾拒入者。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p001·原文件第6行", "note": "原文：上大惊，召建谕之，建称疾不入。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "46a8bd2e-8c95-5967-b843-43bd51afe168", "